    "src/ExchangeConfig.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {IExchangeConfig} from "./interface/IExchangeConfig.sol";
import {Account} from "./lib/storage/Account.sol";
import {Deposit} from "./lib/storage/Deposit.sol";
import {Exchange} from "./lib/storage/Exchange.sol";
import {FeeCollector} from "./lib/storage/FeeCollector.sol";
import {FeeSchedule} from "./lib/storage/FeeSchedule.sol";
import {Liquidator} from "./lib/storage/Liquidator.sol";
import {Token} from "./lib/storage/Token.sol";
import {USD_TOKEN_NAME} from "./share/Constants.sol";
import {ActionType} from "./share/Enums.sol";
import {
    InvalidParameter,
    LiquidatorIsDeleveraging,
    P_ERR_AMT_GT_MAX,
    P_ERR_AMT_NON_ZERO,
    P_ERR_AMT_ZERO,
    P_ERR_BAD_ACCOUNT,
    P_ERR_BAD_ADDR,
    P_ERR_BAD_SIGNER,
    P_ERR_BAD_SUBACCOUNT,
    P_ERR_BAD_VAL,
    P_ERR_FOUND,
    P_ERR_NOT_FOUND,
    PendingDepositFound,
    TokenRemoveProtected
} from "./share/Errors.sol";
import {ActionId} from "./share/UserDefinedTypes.sol";
import {ERC20Helpers} from "./share/tokens/ERC20Helpers.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

contract ExchangeConfig is IExchangeConfig {
    using EnumerableSet for EnumerableSet.Bytes32Set;
    using FeeSchedule for FeeSchedule.DataGlobal;
    using Token for Token.Data;

    /// @dev Maximum batch deposit size in a single call by deposit delegators.
    uint256 private constant MAX_BATCH_DEPOSIT_SIZE = 100;
    uint256 private constant MINIMUM_RESCUE_DELAY = 1 hours;
    uint256 private constant MAXIMUM_RESCUE_DELAY = 7 days;

    /// @inheritdoc IExchangeConfig
    function addToken(bytes32 tokenName, address tokenAddress, address oftAddress, address backingToken) external {
        Exchange.Data storage exchange = Exchange.load();
        EnumerableSet.Bytes32Set storage tokens = exchange.tokens;

        // bytes(0) names not allowed.
        if (tokenName == bytes32(0)) {
            revert InvalidParameter("tokenName", P_ERR_BAD_VAL);
        }

        // Token may already exist.
        if (!tokens.add(tokenName)) {
            revert InvalidParameter("tokenName", P_ERR_FOUND);
        }

        // A token cannot be both a virtual token (i.e. zero address) and an OFT.
        if (oftAddress != address(0) && tokenAddress == address(0)) {
            revert InvalidParameter("oftAddress", P_ERR_NOT_FOUND);
        }

        bool isUsdToken = tokenName == USD_TOKEN_NAME;

        // Tracking token
        Token.Data storage token = Token.load(tokenName);
        token.name = tokenName;

        // Allow virtual tokens but not if the tokenName is the usdToken.
        if (tokenAddress == address(0)) {
            if (backingToken != address(0)) {
                revert InvalidParameter("backingToken", P_ERR_BAD_VAL);
            }

            if (isUsdToken) {
                revert InvalidParameter("tokenAddress", P_ERR_NOT_FOUND);
            }

            if (oftAddress != address(0)) {
                revert InvalidParameter("oftAddress", P_ERR_BAD_VAL);
            }
        } else {
            // Another token is already using this address.
            bytes32 existingTokenName = exchange.tokensByAddress[tokenAddress];
            if (existingTokenName != bytes32(0)) {
                revert InvalidParameter("tokenAddress", P_ERR_FOUND);
            }

            bool isErc20 = ERC20Helpers.isERC20(tokenAddress);

            // Tokens with backing tokens are synthetic tokens
            if (backingToken != address(0)) {
                // Synthetic tokens with backing token must not be real ERC20s
                if (isErc20) {
                    revert InvalidParameter("tokenAddress", P_ERR_FOUND);
                }

                // Backing token must be registered
                bytes32 existingBackingTokenName = exchange.tokensByAddress[backingToken];
                if (existingBackingTokenName == bytes32(0)) {
                    revert InvalidParameter("backingToken", P_ERR_NOT_FOUND);
                }

                // Backing token must be a concrete token (not a virtual or synthetic token)
                Token.Data storage backingTokenData = Token.load(exchange.tokensByAddress[backingToken]);
                if (backingTokenData.tokenAddress == address(0)) {
                    revert InvalidParameter("backingToken", P_ERR_BAD_VAL);
                }

                if (backingTokenData.backingToken != address(0)) {
                    revert InvalidParameter("backingToken", P_ERR_FOUND);
                }

                // Synthetic tokens cannot be withdrawn and cannot have an OFT address
                if (oftAddress != address(0)) {
                    revert InvalidParameter("oftAddress", P_ERR_BAD_VAL);
                }
            } else {
                if (!isErc20) {
                    revert InvalidParameter("tokenAddress", P_ERR_BAD_ADDR);
                }
            }
            token.tokenAddress = tokenAddress;
            token.oftAddress = oftAddress;
            token.backingToken = backingToken;

            // Update the global usdToken.
            if (isUsdToken) {
                Account.DataGlobal storage accountGlobal = Account.load();
                accountGlobal.usdToken = tokenAddress;
            }

            exchange.tokensByAddress[tokenAddress] = tokenName;
        }

        emit TokenAdded(tokenName, tokenAddress);
    }

    /// @inheritdoc IExchangeConfig
    function promoteToken(bytes32 tokenName, address tokenAddress, address oftAddress) external {
        Exchange.Data storage exchange = Exchange.load();
        EnumerableSet.Bytes32Set storage tokens = exchange.tokens;

        // bytes(0) names not allowed.
        if (tokenName == bytes32(0)) {
            revert InvalidParameter("tokenName", P_ERR_BAD_VAL);
        }

        // Token does not exist.
        if (!tokens.contains(tokenName)) {
            revert InvalidParameter("tokenName", P_ERR_NOT_FOUND);
        }

        Token.Data storage token = Token.load(tokenName);

        // Synthetic tokens cannot be promoted to to a concrete token. Promoting it to a real ERC20 would let backing-token balances
        // escape via withdrawals.
        if (token.backingToken != address(0)) {
            revert InvalidParameter("backingToken", P_ERR_FOUND);
        }

        // Token already has a token address (already a real ERC20).
        if (token.tokenAddress != address(0)) {
            revert InvalidParameter("tokenName", P_ERR_FOUND);
        }

        // Must be a valid ERC20.
        if (!ERC20Helpers.isERC20(tokenAddress)) {
            revert InvalidParameter("tokenAddress", P_ERR_BAD_ADDR);
        }

        // Token address already used by another token.
        bytes32 existingTokenName = exchange.tokensByAddress[tokenAddress];
        if (existingTokenName != bytes32(0)) {
            revert InvalidParameter("tokenAddress", P_ERR_FOUND);
        }
        exchange.tokensByAddress[tokenAddress] = tokenName;
        token.tokenAddress = tokenAddress;
        token.oftAddress = oftAddress;

        emit TokenPromoted(tokenName, tokenAddress);
    }

    /// @inheritdoc IExchangeConfig
    function updateActionExpiryBuffer(ActionType action, uint64 buffer) external {
        // Too small a buffer time would cause frequent desync
        if (buffer < 1 hours) {
            revert InvalidParameter("buffer", P_ERR_BAD_VAL);
        }

        Exchange.load().actionExpiryBuffers[action] = buffer;

        emit ActionExpiryBufferUpdated(action, buffer);
    }

    /// @inheritdoc IExchangeConfig
    function updateRescueDelay(uint64 rescueDelay) external {
        if (rescueDelay < MINIMUM_RESCUE_DELAY || rescueDelay > MAXIMUM_RESCUE_DELAY) {
            revert InvalidParameter("rescueDelay", P_ERR_BAD_VAL);
        }

        Exchange.Data storage exchange = Exchange.load();
        exchange.rescueDelay = rescueDelay;

        emit RescueDelayUpdated(rescueDelay);
    }

    /// @inheritdoc IExchangeConfig
    function updateToken(IExchangeConfig.UpdateTokenParams calldata params) external {
        Exchange.Data storage exchange = Exchange.load();
        EnumerableSet.Bytes32Set storage tokens = exchange.tokens;

        // bytes(0) names not allowed.
        if (params.tokenName == bytes32(0)) {
            revert InvalidParameter("tokenName", P_ERR_BAD_VAL);
        }

        // Token doesn't exist.
        if (!tokens.contains(params.tokenName)) {
            revert InvalidParameter("token", P_ERR_NOT_FOUND);
        }

        // Fee is greater than zero then it cannot be larger than minDeposit.
        if (params.depositFee > 0 && params.depositFee >= params.minDeposit) {
            revert InvalidParameter("depositFee", P_ERR_AMT_GT_MAX);
        }

        Token.Data storage token = Token.load(params.tokenName);

        // Cannot enable deposit/withdrawals on a virtual/synthetic token.
        if (token.tokenAddress == address(0) || token.backingToken != address(0)) {
            if (params.depositEnabled) {
                revert InvalidParameter("depositEnabled", P_ERR_BAD_VAL);
            }
            if (params.withdrawEnabled) {
                revert InvalidParameter("withdrawEnabled", P_ERR_BAD_VAL);
            }
        }

        token.depositCapacity = params.depositCapacity;
        token.minDeposit = params.minDeposit;
        token.depositFee = params.depositFee;
        token.withdrawFee = params.withdrawFee;
        token.depositEnabled = params.depositEnabled;
        token.withdrawEnabled = params.withdrawEnabled;

        emit TokenUpdated(params.tokenName, token.tokenAddress);
    }

    /// @inheritdoc IExchangeConfig
    function removeToken(bytes32 tokenName) external {
        Exchange.Data storage exchange = Exchange.load();
        EnumerableSet.Bytes32Set storage tokens = exchange.tokens;
        Token.Data storage token = Token.load(tokenName);
        Account.DataGlobal storage accountGlobal = Account.load();

        // bytes(0) names not allowed.
        if (tokenName == bytes32(0)) {
            revert InvalidParameter("tokenName", P_ERR_BAD_VAL);
        }

        // Protected tokens cannot be removed.
        if (token.removeProtected) {
            revert TokenRemoveProtected(tokenName);
        }

        address tokenAddress = token.tokenAddress;

        // Prohibit removal when there is a non-zero deposit or pending deposit balance.
        // Checks both synthetic and concrete token balances.
        uint256 totalUsedCapacity =
            accountGlobal.totalBackedBalance[tokenAddress] + accountGlobal.totalPendingBalance[tokenAddress];
        uint256 totalBalance = accountGlobal.totalBalance[tokenAddress];
        if (totalUsedCapacity > 0 || totalBalance > 0) {
            revert InvalidParameter("tokenName", P_ERR_AMT_NON_ZERO);
        }

        if (tokenAddress != address(0)) {
            delete exchange.tokensByAddress[tokenAddress];
        }

        // Remove token name from set of tokens available.
        if (!tokens.remove(tokenName)) {
            revert InvalidParameter("tokenName", P_ERR_NOT_FOUND);
        }

        // If we're removing the usdToken, also clear it from `Account.DataGlobal`.
        if (tokenName == USD_TOKEN_NAME) {
            accountGlobal.usdToken = address(0);
        }

        token.remove();
        emit TokenRemoved(tokenName, tokenAddress);
    }

    /// @inheritdoc IExchangeConfig
    function addSequencer(address account) external {
        _verifyAccountAddressNotZeroAddress(account);

        // Only add the sequencer if it isn't already approved.
        Exchange.Data storage exchange = Exchange.load();
        if (exchange.isSequencerApproved[account]) {
            revert InvalidParameter("account", P_ERR_FOUND);
        }

        Account.DataGlobal storage accountGlobal = Account.load();
        if (accountGlobal.excludedAccounts[account]) {
            revert InvalidParameter("account", P_ERR_BAD_ACCOUNT);
        }
        if (accountGlobal.excludedSigners[account]) {
            revert InvalidParameter("account", P_ERR_BAD_SIGNER);
        }

        exchange.isSequencerApproved[account] = true;
        exchange.isSequencerPaused[account] = true;

        accountGlobal.excludedSigners[account] = true;
        accountGlobal.excludedAccounts[account] = true;

        emit SequencerAdded(account);
    }

    /// @inheritdoc IExchangeConfig
    function removeSequencer(address account) external {
        _verifyAccountAddressNotZeroAddress(account);

        // Only remove if sequencer was previously approved (i.e. exists).
        Exchange.Data storage exchange = Exchange.load();
        if (!exchange.isSequencerApproved[account]) {
            revert InvalidParameter("account", P_ERR_NOT_FOUND);
        }
        exchange.isSequencerApproved[account] = false;
        exchange.isSequencerPaused[account] = false;

        emit SequencerRemoved(account);
    }

    /// @inheritdoc IExchangeConfig
    function updateSequencerPaused(address account, bool paused) external {
        _verifyAccountAddressNotZeroAddress(account);

        // Only remove if sequencer was previously approved (i.e. exists).
        Exchange.Data storage exchange = Exchange.load();
        if (!exchange.isSequencerApproved[account]) {
            revert InvalidParameter("account", P_ERR_NOT_FOUND);
        }

        exchange.isSequencerPaused[account] = paused;

        emit SequencerPausedUpdated(account, paused);
    }

    /// @inheritdoc IExchangeConfig
    function addDelegateDepositor(address delegateDepositor) external {
        if (delegateDepositor == address(0)) {
            revert InvalidParameter("delegateDepositor", P_ERR_BAD_ADDR);
        }

        Exchange.Data storage exchange = Exchange.load();
        if (exchange.isDelegateDepositor[delegateDepositor]) {
            revert InvalidParameter("delegateDepositor", P_ERR_FOUND);
        }

        exchange.isDelegateDepositor[delegateDepositor] = true;

        emit DelegateDepositorUpdated(delegateDepositor, true);
    }

    /// @inheritdoc IExchangeConfig
    function removeDelegateDepositor(address delegateDepositor) external {
        Exchange.Data storage exchange = Exchange.load();
        if (!exchange.isDelegateDepositor[delegateDepositor]) {
            revert InvalidParameter("delegateDepositor", P_ERR_NOT_FOUND);
        }

        exchange.isDelegateDepositor[delegateDepositor] = false;

        emit DelegateDepositorUpdated(delegateDepositor, false);
    }

    /// @inheritdoc IExchangeConfig
    function addClaimer(address claimer) external {
        if (claimer == address(0)) {
            revert InvalidParameter("claimer", P_ERR_BAD_ADDR);
        }

        Exchange.Data storage exchange = Exchange.load();
        if (exchange.isClaimer[claimer]) {
            revert InvalidParameter("claimer", P_ERR_FOUND);
        }

        exchange.isClaimer[claimer] = true;

        emit ClaimerUpdated(claimer, true);
    }

    /// @inheritdoc IExchangeConfig
    function removeClaimer(address claimer) external {
        Exchange.Data storage exchange = Exchange.load();
        if (!exchange.isClaimer[claimer]) {
            revert InvalidParameter("claimer", P_ERR_NOT_FOUND);
        }

        exchange.isClaimer[claimer] = false;

        emit ClaimerUpdated(claimer, false);
    }

    /// @inheritdoc IExchangeConfig
    function updateDelegateDepositMaxBatchSize(uint16 delegateDepositMaxBatchSize) external {
        if (delegateDepositMaxBatchSize > MAX_BATCH_DEPOSIT_SIZE) {
            revert InvalidParameter("delegateDepositMaxBatchSize", P_ERR_AMT_GT_MAX);
        }
        Exchange.load().delegateDepositMaxBatchSize = delegateDepositMaxBatchSize;
        emit DelegateDepositMaxBatchSizeUpdated(delegateDepositMaxBatchSize);
    }

    /// @inheritdoc IExchangeConfig
    function updateFeeCollector(address account, bytes32 subaccount) external {
        _verifyAccountAddressNotZeroAddress(account);
        _verifySubaccountNotZeroAddress(subaccount);
        _verifySubaccountNotRegistered(account, subaccount);

        Account.DataGlobal storage accountGlobal = Account.load();
        accountGlobal.excludedSigners[account] = true;
        accountGlobal.excludedAccounts[account] = true;

        FeeCollector.Data storage feeCollector = FeeCollector.load();
        feeCollector.account = account;
        feeCollector.subaccount = subaccount;
        emit FeeCollectorUpdated(account, subaccount);
    }

    /// @inheritdoc IExchangeConfig
    function updateLiquidator(address account, bytes32 subaccount) external {
        Liquidator.Data storage liquidator = Liquidator.load();
        if (liquidator.deleverageMessageIdx != 0) {
            revert LiquidatorIsDeleveraging(ActionId.wrap(0));
        }

        _verifyAccountAddressNotZeroAddress(account);
        _verifySubaccountNotZeroAddress(subaccount);
        _verifySubaccountNotRegistered(account, subaccount);

        Account.load().excludedSigners[account] = true;

        liquidator.account = account;
        liquidator.subaccount = subaccount;
        emit LiquidatorUpdated(account, subaccount);
    }

    /// @inheritdoc IExchangeConfig
    function updatePythLazer(address updatedContract, uint64 updatedMaxAge) external {
        Exchange.Data storage exchange = Exchange.load();
        exchange.pythLazer = updatedContract;
        exchange.pythMaxAge = updatedMaxAge;
        emit PythLazerUpdated(updatedContract, updatedMaxAge);
    }

    /// @inheritdoc IExchangeConfig
    function updateLzEndpointId(uint32 updatedLzEndpointId) external {
        Exchange.Data storage exchange = Exchange.load();
        exchange.lzEndpointId = updatedLzEndpointId;
        emit LzEndpointIdUpdated(updatedLzEndpointId);
    }

    /// @inheritdoc IExchangeConfig
    function updateFeeSchedule(UpdateFeeScheduleParams calldata params) external {
        _verifyMakerTakerFees(params.makerFee, params.takerFee);

        FeeSchedule.Data storage schedule = FeeSchedule.load(params.id);
        if (!schedule.isRegistered) {
            revert InvalidParameter("id", P_ERR_NOT_FOUND);
        }

        schedule.makerFee = params.makerFee;
        schedule.takerFee = params.takerFee;

        emit FeeScheduleUpdated(params.id);
    }

    /// @inheritdoc IExchangeConfig
    function addFeeSchedule(AddFeeScheduleParams calldata params) external returns (uint32) {
        _verifyMakerTakerFees(params.makerFee, params.takerFee);

        uint32 id = FeeSchedule.load().getAndIncrementNextFeeScheduleId();
        FeeSchedule.Data storage schedule = FeeSchedule.load(id);
        schedule.isRegistered = true;
        schedule.makerFee = params.makerFee;
        schedule.takerFee = params.takerFee;

        emit FeeScheduleAdded(id);

        return id;
    }

    /// @inheritdoc IExchangeConfig
    function addEmergencyPauser(address pauser) external {
        if (pauser == address(0)) {
            revert InvalidParameter("pauser", P_ERR_BAD_ADDR);
        }

        Exchange.Data storage exchange = Exchange.load();
        if (exchange.isEmergencyPauser[pauser]) {
            revert InvalidParameter("pauser", P_ERR_FOUND);
        }

        exchange.isEmergencyPauser[pauser] = true;

        emit EmergencyPauserUpdated(pauser, true);
    }

    /// @inheritdoc IExchangeConfig
    function removeEmergencyPauser(address pauser) external {
        Exchange.Data storage exchange = Exchange.load();
        if (!exchange.isEmergencyPauser[pauser]) {
            revert InvalidParameter("pauser", P_ERR_NOT_FOUND);
        }

        exchange.isEmergencyPauser[pauser] = false;

        emit EmergencyPauserUpdated(pauser, false);
    }

    // --- Helpers --- //

    /// @dev Check for address zero, reverting with sequencer specific message.
    function _verifyAccountAddressNotZeroAddress(address account) private pure {
        if (account == address(0)) {
            revert InvalidParameter("account", P_ERR_BAD_ADDR);
        }
    }

    /// @dev Whether the maker and taker fees are within acceptable ranges.
    function _verifyMakerTakerFees(uint32 makerFee, uint32 takerFee) private pure {
        if (makerFee > 1 gwei) {
            revert InvalidParameter("makerFee", P_ERR_AMT_GT_MAX);
        }
        if (takerFee > 1 gwei) {
            revert InvalidParameter("takerFee", P_ERR_AMT_GT_MAX);
        }
        if (makerFee > takerFee) {
            revert InvalidParameter("makerFee", P_ERR_BAD_VAL);
        }
    }

    /// @dev Check for subaccount name not empty.
    function _verifySubaccountNotZeroAddress(bytes32 subaccount) private pure {
        if (subaccount == bytes32(0)) {
            revert InvalidParameter("subaccount", P_ERR_BAD_VAL);
        }
    }

    /// @dev Check whether the subaccount has already been registered or could be due to a pending deposit.
    function _verifySubaccountNotRegistered(address account, bytes32 subaccount) private view {
        Account.Data storage accountData = Account.load(account);

        if (accountData.hasRegistered[subaccount]) {
            revert InvalidParameter("subaccount", P_ERR_BAD_SUBACCOUNT);
        }

        Deposit.Data storage pendingDeposit = accountData.pendingDeposit[subaccount];
        if (pendingDeposit.token != address(0)) {
            revert PendingDepositFound(account, subaccount, pendingDeposit.token, pendingDeposit.amount);
        }
    }
}
"
