    "src/interface/IActionHandler.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {EngineType, OrderSide} from "../share/Enums.sol";
import {ActionId} from "../share/UserDefinedTypes.sol";

interface IActionHandler {
    // --- Events --- //

    /// @notice Emitted when a deposit has been finalized.
    event DepositFinalized(
        address indexed sender,
        bytes32 indexed subaccount,
        address token,
        uint256 amount,
        uint128 fee,
        uint256 balance,
        bytes32 initiatedTxHash,
        uint32 initiatedLogIdx,
        uint64 messageIdx
    );

    /// @notice Emitted when a token conversion is finalized.
    event ConvertFinalized(
        address indexed account,
        bytes32 indexed subaccount,
        bytes32 indexed convertDigest,
        address fromToken,
        address toToken,
        uint128 fromAmount,
        uint128 toAmount,
        uint128 fee,
        uint64 finalizedTimestamp,
        uint64 messageIdx
    );

    /// @notice Emitted when signer is linked to the subaccount (i.e. msg.sender).
    event SignerLinked(
        address indexed sender,
        bytes32 indexed subaccount,
        address indexed signer,
        uint64 linkedTimestamp,
        uint64 messageIdx
    );

    /// @notice Emitted when signer linkage is rejected i.e. the signer has deposited (is already an account).
    event SignerLinkRejected(
        address indexed sender,
        bytes32 indexed subaccount,
        address indexed signer,
        uint64 rejectedTimestamp,
        uint64 messageIdx
    );

    /// @notice Emitted when signer is revoked from the subaccount (i.e. msg.sender).
    event SignerRevoked(
        address indexed sender,
        bytes32 indexed subaccount,
        address indexed signer,
        uint64 revokedTimestamp,
        uint64 messageIdx
    );

    /// @notice Emitted when signer revocation is rejected (i.e. signature validation failed).
    event SignerRevokeRejected(
        address indexed sender,
        bytes32 indexed subaccount,
        address indexed signer,
        uint64 rejectedTimestamp,
        uint64 messageIdx
    );

    /// @notice Emitted when a subaccount initiated a withdrawal.
    event WithdrawInitiated(
        address indexed account,
        bytes32 indexed subaccount,
        bytes32 indexed withdrawDigest,
        address token,
        uint256 amount,
        uint128 fee,
        uint64 initiatedTimestamp,
        uint64 messageIdx
    );

    /// @notice Emitted when a batch is processed.
    event ActionsProcessed(ActionId firstActionId, ActionId lastActionId, uint256 length);

    // --- ActionTypes --- //

    struct FinalizeDepositAction {
        address account;
        bytes32 subaccount;
        address token;
        uint256 amount;
        bytes32 initiatedTxHash;
        uint32 initiatedLogIdx;
        uint64 messageIdx;
    }

    struct InitiateWithdrawAction {
        InitiateWithdrawMessage message;
        bytes signature;
        uint128 fee;
        uint64 messageIdx;
    }

    struct InitiateWithdrawMessage {
        address account;
        bytes32 subaccount;
        address token;
        uint256 amount;
        uint64 nonce;
        uint64 signedAt;
        bytes32 destinationAddress;
        uint32 destinationEndpointId;
    }

    struct ConvertTokenAction {
        ConvertTokenMessage message;
        bytes signature;
        uint128 fee;
        uint128 toAmount;
        uint64 messageIdx;
    }

    struct ConvertTokenMessage {
        address sender;
        bytes32 subaccount;
        address fromToken;
        address toToken;
        uint128 amount;
        uint64 nonce;
        uint64 signedAt;
    }

    struct LinkSignerAction {
        LinkSignerMessage message;
        bytes signature;
        bytes signerSignature;
        uint64 messageIdx;
    }

    struct LinkSignerMessage {
        address sender;
        address signer;
        bytes32 subaccount;
        uint64 nonce;
        uint64 signedAt;
    }

    struct MatchOrdersAction {
        TradeOrder maker;
        TradeOrder taker;
        bytes makerSignature;
        bytes takerSignature;
        uint128 makerFee;
        uint128 takerFee;
        int128 makerRealizedPnl;
        int128 takerRealizedPnl;
        uint128 fillQuantity;
        uint128 fillNotional;
        uint64 messageIdx;
    }

    struct RevokeLinkedSignerAction {
        RevokeLinkedSignerMessage message;
        bytes signature;
        uint64 messageIdx;
    }

    struct RevokeLinkedSignerMessage {
        address sender;
        address signer;
        bytes32 subaccount;
        uint64 nonce;
        uint64 signedAt;
    }

    struct TradeOrder {
        address sender;
        bytes32 subaccount;
        uint128 quantity;
        uint128 price;
        bool reduceOnly;
        OrderSide side;
        EngineType engineType;
        uint32 productId;
        uint64 nonce;
        uint64 signedAt;
    }

    struct UpdateFundingAction {
        uint32 productId;
        int128 fundingDeltaUsd;
        uint64 messageIdx;
    }

    struct FinalizePerpProductUpdateAction {
        uint32 productId;
        uint16 maxLeverage;
        uint128 maxQuantity;
        uint128 maxOpenInterestUsd;
        uint128 maxPositionNotionalUsd;
        uint64 messageIdx;
    }

    struct UpdatePositionFeeAction {
        uint32 productId;
        uint128 positionFeeDeltaUsd;
        uint256 liquidatorCreditAmount;
        uint64 messageIdx;
    }

    struct RealizeFundingAction {
        address account;
        bytes32 subaccount;
        uint32[] productIds;
        uint64 messageIdx;
    }

    struct RealizePnlAction {
        address account;
        bytes32 subaccount;
        uint32 productId;
        int128 costDelta;
        uint64 messageIdx;
    }

    struct InitiatePerpProductDelistAction {
        uint32 productId;
        uint64 messageIdx;
        uint64 pythFee;
        bytes pythPriceUpdate;
    }

    struct FinalizePerpProductDelistAction {
        uint32 productId;
        uint64 messageIdx;
    }

    struct PerpProductDelistPositionSettlementAction {
        address account;
        bytes32 subaccount;
        uint32 productId;
        int128 realizedPnl;
        uint64 messageIdx;
    }

    /// @notice Given a list of signed offchain actions, submit and process (sequencer only).
    /// @param actions Byte array of actions to process
    function processActions(bytes[] calldata actions) external payable;

    /// @notice Simulates `processActions` and always reverts after processing.
    /// @param actions Byte array of actions to simulate.
    /// @param minGasLeft Minimum gas that must remain after each action. Disables if zero.
    function processActionsDryRun(bytes[] calldata actions, uint256 minGasLeft) external payable;

    /// @notice Finalizes a revoked signer when signature verification failed onchain.
    /// @param message Revocation message data to finalize
    function finalizeRevokeLinkedSigner(RevokeLinkedSignerMessage calldata message) external;
}
"
    },
    "src/interface/IExchangeConfig.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {ActionType} from "../share/Enums.sol";

interface IExchangeConfig {
    // --- Events --- //

    /// @notice Emitted when a delegate depositor role for an account has been updated.
    event DelegateDepositorUpdated(address indexed account, bool granted);

    /// @notice Emitted when the Exchange fee collector details are updated.
    event FeeCollectorUpdated(address indexed account, bytes32 indexed subaccount);

    /// @notice Emitted when the delegate deposit max batch size is updated.
    event DelegateDepositMaxBatchSizeUpdated(uint16 delegateDepositMaxBatchSize);

    /// @notice Emitted when a fee schedule is added.
    event FeeScheduleAdded(uint32 indexed id);

    /// @notice Emitted when a fee schedule is updated.
    event FeeScheduleUpdated(uint32 indexed id);

    /// @notice Emitted when the Exchange liquidator details are updated.
    event LiquidatorUpdated(address indexed account, bytes32 indexed subaccount);

    /// @notice Emitted when the Emergency Pauser role is updated for an address.
    event EmergencyPauserUpdated(address indexed pauser, bool enabled);

    /// @notice Emitted when the PythLazer config data is updated.
    event PythLazerUpdated(address pythLazer, uint64 maxAge);

    /// @notice Emitted when the host chain LayerZero endpoint ID is updated.
    event LzEndpointIdUpdated(uint32 indexed lzEndpointId);

    /// @notice Emitted when a sequencer is added.
    event SequencerAdded(address indexed sequencer);

    /// @notice Emitted when a sequencer has their paused state set.
    event SequencerPausedUpdated(address indexed sequencer, bool paused);

    /// @notice Emitted when a sequencer is removed.
    event SequencerRemoved(address indexed sequencer);

    /// @notice Emitted when an action expiry buffer is updated.
    event ActionExpiryBufferUpdated(ActionType indexed action, uint64 buffer);

    /// @notice Emitted when a token is added.
    event TokenAdded(bytes32 indexed tokenName, address tokenAddress);

    /// @notice Emitted when an existing token is removed.
    event TokenRemoved(bytes32 indexed tokenName, address tokenAddress);

    /// @notice Emitted when an existing token is updated.
    event TokenUpdated(bytes32 indexed tokenName, address tokenAddress);

    /// @notice Emitted when a virtual token is promoted.
    event TokenPromoted(bytes32 indexed tokenName, address tokenAddress);

    /// @notice Emitted when the claimer has been updated.
    event ClaimerUpdated(address indexed claimer, bool granted);

    /// @notice Emitted when the rescue delay configuration is updated.
    event RescueDelayUpdated(uint64 rescueDelay);

    // --- Structs --- //

    struct AddFeeScheduleParams {
        /// Percentage fee charged to the maker side, in D9 precision.
        uint32 makerFee;
        /// Percentage fee charged to the taker side, in D9 precision.
        uint32 takerFee;
    }

    struct UpdateFeeScheduleParams {
        /// Id of the fee schedule
        uint32 id;
        /// Percentage fee charged to the maker side, in D9 precision.
        uint32 makerFee;
        /// Percentage fee charged to the taker side, in D9 precision.
        uint32 takerFee;
    }

    /// @dev Deposit and withdrawal settings only affect concrete tokens.
    struct UpdateTokenParams {
        /// Unique token name identifier
        bytes32 tokenName;
        /// Maximum active backed balance in D9, including pending deposits but excluding initiated withdrawals.
        uint256 depositCapacity;
        /// Minimum token amount per deposit, in D9 precision.
        uint256 minDeposit;
        /// Flat fee charged on each deposit, in D9 precision.
        uint128 depositFee;
        /// Flat fee charged on each withdrawal, in D9 precision.
        uint128 withdrawFee;
        /// Whether tokens can be deposited
        bool depositEnabled;
        /// Whether tokens can be withdrawn
        bool withdrawEnabled;
    }

    // --- Mutations --- //

    /// @notice Adds a new token.
    /// @param tokenName Name of token to add
    /// @param tokenAddress ERC20 address, synthetic accounting key, or zero for virtual tokens
    /// @param oftAddress Address of the OFT contract (or OFTAdapter)
    /// @param backingToken Address of the backing token (address(0) if not backed)
    /// @dev Once the USD_TOKEN_NAME has been added it cannot be removed if its used in a product.
    /// @dev tokenName is case sensitive which means USD and usd are treated differently.
    /// @dev Synthetic tokens use a non-ERC20 accounting address and cannot be deposited or withdrawn.
    function addToken(bytes32 tokenName, address tokenAddress, address oftAddress, address backingToken) external;

    /// @notice Updates an existing token with new params.
    /// @param params Token update parameters; all amount fields use D9 precision.
    function updateToken(UpdateTokenParams calldata params) external;

    /// @notice Promotes a virtual token to concrete by providing a new `tokenAddress`.
    /// @param tokenName Name of existing virtual token
    /// @param tokenAddress New token address to associate the virtual token against
    /// @param oftAddress Address of the OFT contract (or OFTAdapter)
    function promoteToken(bytes32 tokenName, address tokenAddress, address oftAddress) external;

    /// @notice Removes an existing token from set of exchange tokens.
    /// @param tokenName Name of the previously configured token to remove
    /// @notice This remove will revert if `token` is `usdToken` or if there is a balance > 0.
    function removeToken(bytes32 tokenName) external;

    /// @notice Adds a new sequencer to the approved mapping.
    /// @param account Address of the approved sequencer
    function addSequencer(address account) external;

    /// @notice Removes an existing sequencer from the approved mapping.
    /// @param account Address of the sequencer to remove
    function removeSequencer(address account) external;

    /// @notice Sets the paused state of a sequencer. Requests are only accepted from enabled sequencers.
    /// @param sequencer Address of the sequencer whose pause state is to be altered
    /// @param paused Whether the sequencer is paused
    function updateSequencerPaused(address sequencer, bool paused) external;

    /// @notice Updates the expiry time for a category of actions.
    /// @param action The category of action whose buffer will be updated
    /// @param buffer Amount of time after signing that an action is valid to execution, in seconds
    function updateActionExpiryBuffer(ActionType action, uint64 buffer) external;

    /// @notice Updates the details for the Exchange's fee collector.
    /// @param account Address that will accrue the Exchange fees
    /// @param subaccount Subaccount identifier for the address collecting the Exchange fees
    function updateFeeCollector(address account, bytes32 subaccount) external;

    /// @notice Updates a fee schedule.
    /// @param params Update fee schedule params
    function updateFeeSchedule(UpdateFeeScheduleParams calldata params) external;

    /// @notice Adds a new fee schedule.
    /// @param params Add new fee schedule params
    function addFeeSchedule(AddFeeScheduleParams calldata params) external returns (uint32);

    /// @notice Updates the details for the Exchange's liquidator account.
    /// @param account Address that accrues liquidated positions
    /// @param subaccount Subaccount identifier of the liquidator account
    function updateLiquidator(address account, bytes32 subaccount) external;

    /// @notice Updates the details for the PythLazer contract used for price verification.
    /// @param updatedContract Address of the PythLazer contract
    /// @param updatedMaxAge Maximum price age in seconds
    function updatePythLazer(address updatedContract, uint64 updatedMaxAge) external;

    /// @notice Updates the host chain LayerZero endpoint ID.
    /// @param updatedEndpointId Host chain LayerZero endpoint ID
    function updateLzEndpointId(uint32 updatedEndpointId) external;

    /// @notice Grants the delegate depositor role to an address.
    /// @param delegateDepositor who will be granted the role, reverts if role is currently granted
    function addDelegateDepositor(address delegateDepositor) external;

    /// @notice Removes the delegate depositor role from an address.
    /// @param delegateDepositor who will have their the role remove, reverts if role is not currently granted
    function removeDelegateDepositor(address delegateDepositor) external;

    /// @notice Updates the maximum number of deposits that a delegate depositor can make in a batch.
    /// @param delegateDepositMaxBatchSize maximum number of accounts that can passed into depositOnBehalf
    function updateDelegateDepositMaxBatchSize(uint16 delegateDepositMaxBatchSize) external;

    /// @notice Grants the emergency pauser role to an address.
    /// @param pauser that will be granted the role, reverting if role is currently granted
    function addEmergencyPauser(address pauser) external;

    /// @notice Remove the emergency pauser role from an address.
    /// @param pauser that will have their the role remove, reverting if role is not currently granted
    function removeEmergencyPauser(address pauser) external;

    /// @notice Grants the claimer role to an address.
    /// @param claimer who will be granted the role, reverts if role is currently granted
    function addClaimer(address claimer) external;

    /// @notice Revokes the claimer role from an address.
    /// @param claimer who will have their the role remove, reverts if role is not currently granted
    function removeClaimer(address claimer) external;

    /// @notice Updates the delay before funds can be rescued from a withdrawal.
    /// @param rescueDelay New delay in seconds
    function updateRescueDelay(uint64 rescueDelay) external;
}
"
    },
    "src/interface/IExchangeGateway.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {IPerpEngine} from "../interface/IPerpEngine.sol";
import {Deposit} from "../lib/storage/Deposit.sol";
import {FeeSchedule} from "../lib/storage/FeeSchedule.sol";
import {PerpPosition} from "../lib/storage/PerpPosition.sol";
import {PerpProduct} from "../lib/storage/PerpProduct.sol";
import {Token} from "../lib/storage/Token.sol";
import {Withdraw} from "../lib/storage/Withdraw.sol";
import {ActionType, EngineType} from "../share/Enums.sol";

interface IExchangeGateway {
    // --- Events --- //

    /// @notice Emitted when the exchange pause status has transitioned state.
    event ExchangePauseUpdated(address indexed account, bool isPaused);

    /// @notice Emitted when a public indexer ping is recorded.
    /// @dev This is a permissionless offchain indexing aid, not an authenticated liveness signal.
    event Ping(address indexed sender, uint64 timestamp);

    /// @notice Emitted when a fee has been credited to a collector, but is yet to be transferred.
    event FeeAccrued(
        address indexed account,
        bytes32 indexed subaccount,
        address token,
        uint256 feeAmount,
        uint256 balance,
        uint64 messageIdx
    );

    /// @notice Emitted when a subaccount's position is transferred to another subaccount
    event PositionTransferred(
        uint32 indexed productId,
        EngineType indexed engineType,
        address accountFrom,
        bytes32 subaccountFrom,
        address accountTo,
        bytes32 subaccountTo,
        int128 amount
    );

    /// @notice Emitted when an address registry record is updated.
    event RegistryRecordUpdated(bytes32 indexed name, address indexed record);

    // --- Multicall --- //

    /// @notice Batches multiple owner calls into a single atomic transaction.
    /// @dev Uses `address(this).delegatecall` so that `msg.sender` is preserved for access-control checks.
    /// @param data Array of ABI-encoded function calls to execute on the gateway.
    /// @return results Array of ABI-encoded return values from each call.
    function multicall(bytes[] calldata data) external returns (bytes[] memory results);

    // --- AddressRegistry --- //

    /// @notice Update the exchange's address registry by `name` and `record`.
    /// @param name Name of the record we want to update or add
    /// @param record Address of the contract we want to set
    function updateRegistryRecord(bytes32 name, address record) external;

    // --- Ping --- //

    /// @notice Records a public exchange ping for offchain indexers.
    /// @dev Permissionless by design: any sender can emit this log so indexers can observe a recent gateway event
    ///      without relying on empty-block assumptions or external checkpointing.
    function ping() external;

    // -- EmergencyPause -- //

    /// @notice Prevents deposits, withdrawals and trading actions on the exchange.
    function emergencyPause() external;

    /// @notice Enables deposits, withdrawals and trading actions on the exchange.
    function emergencyUnpause() external;

    // --- PerpEngine --- //

    /// @notice Registers a product (i.e. trading pair) against an engine for trading.
    /// @param params AddProductParams struct for product configuration
    function registerPerpProduct(IPerpEngine.RegisterPerpProductParams calldata params) external returns (uint32);

    /// @notice Updates an existing product (i.e. trading pair).
    /// @param params struct for updating product configuration
    function updatePerpProduct(IPerpEngine.UpdatePerpProductParams calldata params) external;

    /// @notice Updates an existing perp product's Pyth feed id.
    function updatePerpProductPythFeedId(uint32 productId, uint32 pythFeedId) external;

    /// @notice Activates a pending perp product.
    function activatePerpProduct(uint32 productId) external;

    /// @notice Initiates a perp product delist. Offchain engine uses the latest available mark price to delist.
    /// @param productId Id of the perp product to delist
    function delistPerpProduct(uint32 productId) external;

    // --- PerpEngineViews --- //

    /// @notice Returns a perp product by its `productId`.
    /// @param productId Id of the targeted perp product
    function getPerpProduct(uint32 productId) external view returns (PerpProduct.Info memory);

    /// @notice Returns the pending perp product update for `productId`, if one exists.
    /// @param productId Id of the targeted perp product
    function getPendingPerpProductUpdate(uint32 productId)
        external
        view
        returns (IPerpEngine.UpdatePerpProductParams memory);

    /// @notice Returns the next perp product id that will be assigned on registration.
    function getNextPerpProductId() external view returns (uint32);

    /// @notice Returns a perp position by its `sender` and `subaccount` in `product`.
    /// @param sender Address of the account owner
    /// @param subaccount Subaccount the position belongs to
    /// @param productId Product the position was opened on
    function getPerpPosition(address sender, bytes32 subaccount, uint32 productId)
        external
        view
        returns (PerpPosition.Data memory);

    // --- GatewayViews --- //

    /// @notice Returns the balance of an account's subaccount for a specific token in D9.
    /// @param account Address of the account owner
    /// @param subaccount Subaccount belonging to the account
    /// @param token Address of token to check balances of
    function getAccountBalance(address account, bytes32 subaccount, address token) external view returns (uint256);

    /// @notice Returns whether the account's subaccount has been registered.
    /// @param account Address of the account owner
    /// @param subaccount Subaccount belonging to the account
    function getAccountHasRegistered(address account, bytes32 subaccount) external view returns (bool);

    /// @notice Returns the linked signer for the account's subaccount
    /// @param account Address of the account owner
    /// @param subaccount Subaccount belonging to the account
    function getAccountLinkedSigners(address account, bytes32 subaccount) external view returns (address[] memory);

    /// @notice Returns the number of positions that the account's subaccount has open.
    /// @param account Address of the account owner
    /// @param subaccount Subaccount belonging to the account
    function getAccountOpenPositions(address account, bytes32 subaccount) external view returns (uint128);

    /// @notice Returns a pending deposit by `account` and `subaccount`.
    /// @param account Address of the account owner
    /// @param subaccount Subaccount belonging to the account
    function getAccountPendingDeposit(address account, bytes32 subaccount) external view returns (Deposit.Data memory);

    /// @notice Returns a pending withdraw by`account` and `subaccount`.
    /// @param account Address of the account owner
    /// @param withdrawDigest identifier for the withdraw, EIP712 domain digest of the withdraw data
    function getAccountPendingWithdraw(address account, bytes32 withdrawDigest)
        external
        view
        returns (Withdraw.Data memory);

    /// @notice Returns the number of registered subaccounts.
    /// @param account Address of the account owner
    function getAccountRegisteredSubaccounts(address account) external view returns (uint32);

    /// @notice Returns the `account` whose `subaccount` the signer is linked with.
    /// @param linkedSigner the active linked signer who is being searched on.
    /// @return accountLinkedToSigner when signer is active, otherwise address zero.
    function getAccountGlobalLinkedSignersToAccount(address linkedSigner) external view returns (address);

    /// @notice Returns the balance held by the exchange, sum of all accounts holdings.
    /// @param token Address of the token to retrieve the details on
    function getAccountGlobalTotalBalance(address token) external view returns (uint256);

    /// @notice Returns the total backed balance held by the exchange which include balances converted to synthetic tokens,
    /// sum of all accounts backed balances.
    /// @param token Address of the token to retrieve the details on
    function getAccountGlobalTotalBackedBalance(address token) external view returns (uint256);

    /// @notice Returns the total pending balance held by the exchange, sum of all accounts pending deposits.
    /// @param token Address of the token to retrieve the details on
    function getAccountGlobalTotalPendingBalance(address token) external view returns (uint256);

    /// @notice Returns the settlement stablecoin address.
    function getAccountGlobalUsdToken() external view returns (address);

    /// @notice Returns the amount of time , after an action is signed tha it remains valid for execution, in seconds.
    /// @param action type of action to get the buffer for
    function getExchangeActionExpiryBuffer(ActionType action) external view returns (uint64);

    /// @notice Returns the configured rescue delay in seconds.
    function getExchangeRescueDelay() external view returns (uint64);

    /// @notice Returns the timestamp of the last recorded ping.
    function getExchangeLastPingTimestamp() external view returns (uint64);

    /// @notice Returns the maximum number of deposits that a delegate depositor can submit in one batch.
    function getExchangeDelegateDepositMaxBatchSize() external view returns (uint16);

    /// @notice Returns the `account` for the PythLazer contract used for price verification.
    function getExchangePythLazer() external view returns (address pythLazer, uint64 pythMaxAge);

    /// @notice Returns true if the sequencer is approved, false otherwise.
    /// @param sequencer Sequencer address to check
    function getExchangeSequencer(address sequencer) external view returns (bool isApproved, bool isPaused);

    /// @notice Returns an array of token names.
    function getExchangeTokens() external view returns (bytes32[] memory);

    /// @notice Returns the `account` and `subaccount` that accrue the exchange fees.
    function getFeeCollector() external view returns (address feeCollectorAccount, bytes32 feeCollectorSubaccount);

    /// @notice Returns the FeeSchedule for the given id.
    function getFeeSchedule(uint32 feeScheduleId) external view returns (FeeSchedule.Data memory);

    /// @notice Returns the `account` and `subaccount` that deals with liquidated positions.
    function getLiquidator() external view returns (address liquidatorAccount, bytes32 liquidatorSubaccount);

    /// @notice Returns the token details, that was at one point supported by the exchange.
    /// @param tokenName Name of the token to retrieve the details for
    function getToken(bytes32 tokenName) external view returns (Token.Data memory);

    /// @notice Returns true if `delegator` is an approved delegate depositor, false otherwise.
    /// @param delegator Address of delegator to verify
    function isDelegateDepositor(address delegator) external view returns (bool);

    /// @notice Returns true if the exchange has been paused for deposits, withdraws and trades, false otherwise.
    function isEmergencyPaused() external view returns (bool);

    /// @notice Returns true if the account has been granted the privilege to performs an emergency pause, false otherwise.
    /// @param account Address of pauser to verify
    function isEmergencyPauser(address account) external view returns (bool);

    /// @notice Returns true if `sequencer` is an approved sequencer, false otherwise.
    /// @param sequencer Address of sequencer to verify
    function isSequencerApproved(address sequencer) external view returns (bool);

    /// @notice Returns true if the `claimer` is an approved claimer, false otherwise.
    /// @param claimer Address of the claimer to verify.
    function isClaimer(address claimer) external view returns (bool);
}
"
    },
    "src/interface/IPerpEngine.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {OrderSide, ProductStatus} from "../share/Enums.sol";
import {ActionId} from "../share/UserDefinedTypes.sol";
import {IActionHandler} from "./IActionHandler.sol";

interface IPerpEngine {
    // --- Events --- //

    /// @notice Emitted when a perp product is registered.
    event PerpProductRegistered(uint32 indexed productId, bytes32 baseTokenName, bytes32 quoteTokenName);

    /// @notice Emitted when a perp product's Pyth feed id has been updated.
    event PerpProductPythFeedIdUpdated(uint32 indexed productId, uint32 pythFeedId);

    /// @notice Emitted when a perp product's status has been updated.
    event PerpProductStatusUpdated(uint32 indexed productId, ProductStatus status);

    /// @notice Emitted when a perp product has been updated.
    event PerpProductUpdated(uint32 indexed productId);

    /// @notice Emitted when a perp product configuration update has been initiated by the owner.
    event PerpProductUpdateInitiated(uint32 indexed productId);

    /// @notice Emitted when a pending perp product configuration update has been finalized by the sequencer.
    event PerpProductUpdateFinalized(uint32 indexed productId, uint64 messageIdx);

    /// @notice Emitted when the owner has invoked delisting for a perp product.
    event PerpProductDelistInvoked(uint32 indexed productId);

    /// @notice Emitted when the sequencer has initiated the delist context for a perp product.
    event PerpProductDelistInitiated(uint32 indexed productId, uint256 expiryPrice, uint64 messageIdx);

    /// @notice Emitted when delisting is finalized.
    event PerpProductDelistFinalized(uint32 indexed productId, uint256 expiryPrice, uint64 messageIdx);

    /// @notice Emitted when an open position on a delisting product is cash-settled.
    event PerpProductDelistPositionSettlement(
        address indexed account,
        bytes32 indexed subaccount,
        uint32 indexed productId,
        int128 size,
        int128 realizedPnl,
        uint64 messageIdx
    );

    /// @notice Emitted when a perp product's cumulative funding is updated.
    event PerpProductFundingUpdated(
        uint32 indexed productId, int256 fundingUsd, int256 cumulativeFundingUsd, uint64 messageIdx
    );

    /// @notice Emitted when a perp product's cumulative position fee is updated.
    event PerpProductPositionFeeUpdated(
        uint32 indexed productId,
        uint128 positionFeeDeltaUsd,
        uint128 cumulativePositionFeeUsd,
        uint256 liquidatorCreditAmount,
        uint64 messageIdx
    );

    /// @notice Emitted when a fill notional mismatch is detected.
    event PerpFillNotionalMismatch(ActionId id, uint128 externalValue, uint128 internalValue, uint128 tolerance);

    /// @notice Emitted when two orders in a perp product match.
    event PerpOrderMatched(
        uint32 indexed productId,
        address indexed maker,
        address indexed taker,
        bytes32 makerSubaccount,
        bytes32 takerSubaccount,
        OrderSide makerSide,
        OrderSide takerSide,
        uint128 fillQuantity,
        uint128 price,
        uint128 makerFee,
        uint128 takerFee,
        uint64 messageIdx
    );

    /// @notice Emitted when funding for positions held by `account/subaccount` is realized.
    event PerpFundingRealized(
        address indexed account,
        bytes32 indexed subaccount,
        uint32[] productIds,
        int256 realizedFundingUsd,
        uint64 messageIdx
    );

    /// @notice Emitted when PnL for a position is realized ad-hoc.
    event PerpPnlRealized(
        address indexed account,
        bytes32 indexed subaccount,
        uint32 indexed productId,
        int128 costDelta,
        uint64 messageIdx
    );

    // --- Structs --- //

    /// @notice Params used to register a perp product.
    struct RegisterPerpProductParams {
        bytes32 baseTokenName;
        bytes32 quoteTokenName;
        ProductStatus status;
        uint16 maxLeverage;
        uint32 feeScheduleId;
        uint32 pythFeedId;
        uint128 tickSize;
        uint128 maxQuantity;
        uint128 lotSize;
        uint128 maxOpenInterestUsd;
        uint128 maxPositionNotionalUsd;
    }

    /// @notice Params used to update a perp product.
    struct UpdatePerpProductParams {
        uint32 id;
        uint16 maxLeverage;
        uint128 maxQuantity;
        uint128 maxOpenInterestUsd;
        uint128 maxPositionNotionalUsd;
    }

    struct ExecuteMatchDigests {
        bytes32 maker; // Hash of the EIP-712 maker message
        bytes32 taker; // Hash of the EIP-712 taker message
    }

    /// @dev Data structure to hold the fill data for a position settlement.
    struct FillData {
        uint128 quantity;
        uint128 price;
        int128 oldSize;
        int128 newSize;
        int128 sizeDelta;
    }

    /// @dev Data structure to hold the fill data for a position settlement from an external source.
    struct ExternalFillData {
        uint128 eFillNotional;
        int128 eRealizedPnl;
    }

    /// @notice Initiates a sequencer-delivered delist context for a perp product.
    /// @param id Id of the initiate delist action in the `processActions` array
    /// @param action Action containing product id, engine message index, and Pyth price update
    function initiateDelist(ActionId id, IActionHandler.InitiatePerpProductDelistAction calldata action)
        external
        payable;

    /// @notice Cash-settles a single open position during a product delist.
    /// @param id Id of the settle action in the `processActions` array
    /// @param action Settlement action with account/subaccount/productId, engine-reported realized PnL,
    ///               expiry price, and engine message index
    function settleDelistPosition(ActionId id, IActionHandler.PerpProductDelistPositionSettlementAction calldata action)
        external
        payable;

    /// @notice Finalizes a perp product delist after all positions have been settled and open interest is zero.
    /// @param id Id of the finalize delist action in the `processActions` array
    /// @param action Action containing product id and engine message index
    function finalizeDelist(ActionId id, IActionHandler.FinalizePerpProductDelistAction calldata action)
        external
        payable;

    /// @notice Finalizes and applies a pending product update.
    /// @param id Id of the finalize action in the `processActions` array
    /// @param action The sequencer-finalized pending product update
    function finalizeUpdate(ActionId id, IActionHandler.FinalizePerpProductUpdateAction calldata action)
        external
        payable;

    /// @notice Match a maker and take order by its product.
    /// @param id Id of the match action in the `processActions` array
    /// @param action The match action containing maker and taker orders with signatures and fees
    /// @param digests Digests of the EIP-712 maker and taker messages
    function executeMatch(
        ActionId id,
        IActionHandler.MatchOrdersAction calldata action,
        ExecuteMatchDigests calldata digests
    ) external payable;

    /// @notice Updates a perp product's funding, adding `cumulativeFundingUsd`.
    /// @param id Id of the update funding action in the `processActions` array
    /// @param productId Id of the product to update funding on
    /// @param cumulativeFundingUsd Funding USD delta to update with
    /// @param messageIdx Message index that produced funding update
    function updateFunding(ActionId id, uint32 productId, int128 cumulativeFundingUsd, uint64 messageIdx)
        external
        payable;

    /// @notice Updates a perp product's position fee, adding `positionFeeDeltaUsd`.
    /// @param id Id of the update position fee action in the `processActions` array
    /// @param productId Id of the product to update position fee on
    /// @param positionFeeDeltaUsd Position fee USD delta to update with
    /// @param liquidatorCreditAmount Amount to credit to the configured liquidator
    /// @param messageIdx Message index that produced position fee update
    function updatePositionFee(
        ActionId id,
        uint32 productId,
        uint128 positionFeeDeltaUsd,
        uint256 liquidatorCreditAmount,
        uint64 messageIdx
    ) external payable;

    /// @notice Realizes funding for a list of products for a specific account/subaccount.
    /// @param id Id of the realize funding action in the `processActions` array
    /// @param account Address to realize funding for (cannot be a signer)
    /// @param subaccount Subaccount to realize funding for
    /// @param productIds Sorted (asc) list of all productIds with open positions
    /// @param messageIdx Message index that produced this action
    /// @dev This function will no-op if all parameters are valid but positions are fresh or funding is net zero.
    function realizeFunding(
        ActionId id,
        address account,
        bytes32 subaccount,
        uint32[] calldata productIds,
        uint64 messageIdx
    ) external payable;

    /// @notice Realizes PnL by adjusting position cost and user balance.
    /// @param id Id of the realize pnl action in the `processActions` array
    /// @param account Address of the account holding the position
    /// @param subaccount Subaccount holding the position
    /// @param productId Product ID of the position to realize PnL for
    /// @param costDelta Cost adjustment to apply to position and balance
    /// @param messageIdx Message index that produced this action
    function realizePnl(
        ActionId id,
        address account,
        bytes32 subaccount,
        uint32 productId,
        int128 costDelta,
        uint64 messageIdx
    ) external payable;
}
"
    },
    "src/lib/external/pyth/PythLazerLib.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

// @see: https://github.com/pyth-network/pyth-crosschain/blob/main/lazer/contracts/evm/src/PythLazerLib.sol
//
// NOTE: Adjusted to use `bytes memory update` from `bytes calldata update`.
library PythLazerLib {
    enum PriceFeedProperty {
        Price,
        BestBidPrice,
        BestAskPrice,
        PublisherCount,
        Exponent,
        Confidence,
        FundingRate,
        FundingTimestamp,
        FundingRateInterval,
        MarketSession,
        EmaPrice,
        EmaConfidence,
        FeedUpdateTimestamp
    }

    enum Channel {
        Invalid,
        RealTime,
        FixedRate50,
        FixedRate200
    }

    function parsePayloadHeader(bytes memory update)
        internal
        pure
        returns (uint64 timestamp, Channel channel, uint8 feedsLen, uint16 pos)
    {
        uint32 FORMAT_MAGIC = 2479346549;

        pos = 0;
        // Manual byte concatenation for uint32/bytes4
        bytes4 magicBytes = bytes4(abi.encodePacked(update[pos], update[pos + 1], update[pos + 2], update[pos + 3]));
        uint32 magic = uint32(magicBytes);
        pos += 4;
        if (magic != FORMAT_MAGIC) {
            revert("invalid magic");
        }

        // Manual byte concatenation for uint64/bytes8
        bytes8 timestampBytes = bytes8(
            abi.encodePacked(
                update[pos],
                update[pos + 1],
                update[pos + 2],
                update[pos + 3],
                update[pos + 4],
                update[pos + 5],
                update[pos + 6],
                update[pos + 7]
            )
        );
        timestamp = uint64(timestampBytes);
        pos += 8;

        channel = Channel(uint8(update[pos]));
        pos += 1;
        feedsLen = uint8(update[pos]);
        pos += 1;
    }

    function parseFeedHeader(bytes memory update, uint16 pos)
        internal
        pure
        returns (uint32 feed_id, uint8 num_properties, uint16 new_pos)
    {
        // Manual byte concatenation for uint32/bytes4
        bytes4 feedIdBytes = bytes4(abi.encodePacked(update[pos], update[pos + 1], update[pos + 2], update[pos + 3]));
        feed_id = uint32(feedIdBytes);
        pos += 4;
        num_properties = uint8(update[pos]);
        pos += 1;
        new_pos = pos;
    }

    function parseFeedProperty(bytes memory update, uint16 pos)
        internal
        pure
        returns (PriceFeedProperty property, uint16 new_pos)
    {
        property = PriceFeedProperty(uint8(update[pos]));
        pos += 1;
        new_pos = pos;
    }

    function parseFeedValueUint64(bytes memory update, uint16 pos)
        internal
        pure
        returns (uint64 value, uint16 new_pos)
    {
        // Manual byte concatenation for uint64/bytes8
        bytes8 valueBytes = bytes8(
            abi.encodePacked(
                update[pos],
                update[pos + 1],
                update[pos + 2],
                update[pos + 3],
                update[pos + 4],
                update[pos + 5],
                update[pos + 6],
                update[pos + 7]
            )
        );
        value = uint64(valueBytes);
        pos += 8;
        new_pos = pos;
    }

    function parseFeedValueInt64(bytes memory update, uint16 pos) internal pure returns (int64 value, uint16 new_pos) {
        // Manual byte concatenation for int64/bytes8
        bytes8 valueBytes = bytes8(
            abi.encodePacked(
                update[pos],
                update[pos + 1],
                update[pos + 2],
                update[pos + 3],
                update[pos + 4],
                update[pos + 5],
                update[pos + 6],
                update[pos + 7]
            )
        );
        value = int64(uint64(valueBytes));
        pos += 8;
        new_pos = pos;
    }

    function parseFeedValueUint16(bytes memory update, uint16 pos)
        internal
        pure
        returns (uint16 value, uint16 new_pos)
    {
        // Manual byte concatenation for uint16/bytes2
        bytes2 valueBytes = bytes2(abi.encodePacked(update[pos], update[pos + 1]));
        value = uint16(valueBytes);
        pos += 2;
        new_pos = pos;
    }

    function parseFeedValueInt16(bytes memory update, uint16 pos) internal pure returns (int16 value, uint16 new_pos) {
        // Manual byte concatenation for int16/bytes2
        bytes2 valueBytes = bytes2(abi.encodePacked(update[pos], update[pos + 1]));
        value = int16(uint16(valueBytes));
        pos += 2;
        new_pos = pos;
    }

    function parseFeedValueUint8(bytes memory update, uint16 pos) internal pure returns (uint8 value, uint16 new_pos) {
        value = uint8(update[pos]);
        pos += 1;
        new_pos = pos;
    }
}
"
    },
    "src/lib/storage/Account.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {IActionHandler} from "../../interface/IActionHandler.sol";
import {ActionType} from "../../share/Enums.sol";
import {InvalidNonce, InvalidSigner, SignerNotFound, SubaccountNotFound} from "../../share/Errors.sol";
import {ActionId} from "../../share/UserDefinedTypes.sol";
import {Deposit} from "./Deposit.sol";
import {Withdraw} from "./Withdraw.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import {SafeCastLib} from "solady/utils/SafeCastLib.sol";

library Account {
    using Account for Account.Data;
    using EnumerableSet for EnumerableSet.AddressSet;
    using SafeCastLib for uint128;
    using SafeCastLib for uint256;
    using SafeCastLib for int256;
    using SafeCastLib for int128;

    bytes32 constant _SLOT_PATH = keccak256(abi.encode("xyz.meridian.Account.Data"));

    // --- Storage --- //

    struct DataGlobal {
        /// Exchange settlement stablecoin address
        address usdToken;
        // Total backed balance across all concrete tokens, excludes virtual/synthetic tokens.
        mapping(address token => uint256 amount) totalBackedBalance;
        /// Total token deposit balance across all accounts
        mapping(address token => uint256 amount) totalBalance;
        /// Total pending token deposit balance across all accounts
        mapping(address token => uint256 amount) totalPendingBalance;
        /// Signer to the msg.sender (account) address (one-time linking)
        mapping(address signer => address account) linkedSignersToAccount;
        /// Whether a Signer has already been used or is excluded from being a Signer
        mapping(address signer => bool excluded) excludedSigners;
        /// Whether an Account is forbidden from trading related operations (trade, deposit, withdraw)
        mapping(address account => bool excluded) excludedAccounts;
    }

    struct Data {
        /// The account owner address
        address sender;
        /// Count of registered subaccounts after finalized deposit.
        uint32 registeredSubaccounts;
        /// Token deposit balance of account by subaccount
        mapping(bytes32 subaccount => mapping(address token => uint256 amount)) balance;
        /// Whether the subaccount has ever had a prior deposit
        mapping(bytes32 subaccount => bool hasDeposited) hasRegistered;
        /// Whether the nonce of the sender (account or signer) has been used (by actionType)
        mapping(address sender => mapping(ActionType => mapping(uint64 nonce => bool hasUsed))) usedNonces;
        /// Linked signer by subaccount approved for tx signing
        mapping(bytes32 subaccount => EnumerableSet.AddressSet linkedSigner) linkedSigners;
        /// Number of open positions by subaccount
        mapping(bytes32 subaccount => uint128 amount) openPositions;
        /// Number of open positions by subaccount and quote token
        mapping(bytes32 subaccount => mapping(address quoteToken => uint128 amount)) openPositionsByQuoteToken;
        /// Mapping of subaccount to a pending deposit
        mapping(bytes32 subaccount => Deposit.Data pendingDeposit) pendingDeposit;
        /// Mapping of the withdraw digest to a pending withdraw
        mapping(bytes32 digest => Withdraw.Data pendingWithdraw) pendingWithdraw;
        /// @dev Mapping of pending signer revocations that failed signature validation.
        /// When a revoke signature fails validation in `_handleRevokeLinkedSigner`, the attempted
        /// revocation is recorded here and marked as pending. The revocation remains pending until
        /// `finalizeRevokeLinkedSigner` is called.
        mapping(bytes32 subaccount => mapping(address signer => bool pending)) pendingSignerRevoke;
    }

    // --- Load --- //

    function load() internal pure returns (DataGlobal storage $) {
        bytes32 s = _SLOT_PATH;
        assembly {
            $.slot := s
        }
    }

    function load(address account) internal pure returns (Data storage $) {
        bytes32 s = keccak256(abi.encode("xyz.meridian.Account.Data", account));
        assembly {
            $.slot := s
        }
    }

    // --- Global --- //

    /// @dev Given an account address or signer address, return the associated account.
    function resolveAccount(DataGlobal storage self, address accountOrSigner) internal view returns (Data storage) {
        address accountAddress = self.linkedSignersToAccount[accountOrSigner];

        // 0x eq no linked signer, so it's an account (which or may or may not exist).
        if (accountAddress == address(0)) {
            return Account.load(accountOrSigner);
        }
        return Account.load(accountAddress);
    }

    /// @notice This function assumes signature validations have been performed externally.
    /// @dev Links a signer, marks nonce as used, and return true if success, false otherwise.
    function linkSigner(DataGlobal storage self, IActionHandler.LinkSignerMessage memory message, ActionId id)
        internal
        returns (bool)
    {
        Account.Data storage account = Account.load(message.sender);

        if (account.isNonceUsed(message.sender, ActionType.LinkSigner, message.nonce)) {
            revert InvalidNonce(id, message.nonce);
        }

        // Excluded addresses cannot be linked (e.g. subaccounts, system accounts).
        if (self.excludedSigners[message.signer]) {
            // Deposits automatically add `msg.sender` to an excluded signers mapping as accounts cannot be
            // used as a linked signer for another account. Here we verify that if the signer is an account then
            // flag `nonce` used and return false.
            //
            // However, if we are attempting to relink and previously revoked signer then throw a revert.
            if (Account.load(message.signer).sender != address(0)) {
                account.usedNonces[message.sender][ActionType.LinkSigner][message.nonce] = true;
                return false;
            }
            revert InvalidSigner(id, message.signer);
        }

        if (!account.isSubaccountRegistered(message.subaccount)) {
            revert SubaccountNotFound(id, message.sender, message.subaccount);
        }

        self.linkedSignersToAccount[message.signer] = message.sender;
        self.excludedSigners[message.signer] = true;

        account.linkedSigners[message.subaccount].add(message.signer);
        account.usedNonces[message.sender][ActionType.LinkSigner][message.nonce] = true;

        return true;
    }

    /// @notice Revokes a signer from a subaccount and marks the given nonce as used.
    /// @dev Once revoked the signer cannot be be relinked to another subaccount.
    function revokeSigner(DataGlobal storage self, IActionHandler.RevokeLinkedSignerMessage memory message, ActionId id)
        internal
    {
        Account.Data storage account = Account.load(message.sender);

        if (!account.isSubaccountRegistered(message.subaccount)) {
            revert SubaccountNotFound(id, message.sender, message.subaccount);
        }
        if (account.isNonceUsed(message.sender, ActionType.RevokeLinkedSigner, message.nonce)) {
            revert InvalidNonce(id, message.nonce);
        }
        if (!account.linkedSigners[message.subaccount].remove(message.signer)) {
            revert SignerNotFound(id, message.sender, message.subaccount, message.signer);
        }

        delete self.linkedSignersToAccount[message.signer];
        account.usedNonces[message.sender][ActionType.RevokeLinkedSigner][message.nonce] = true;
        self.excludedAccounts[message.signer] = true;
    }

    // --- Instance --- //

    /// @dev Returns true if subaccount has been registered, false otherwise.
    function isSubaccountRegistered(Data storage self, bytes32 subaccount) internal view returns (bool) {
        return self.hasRegistered[subaccount];
    }

    /// @dev Returns true if nonce has been used, false otherwise.
    function isNonceUsed(Data storage self, address sender, ActionType actionType, uint64 nonce)
        internal
        view
        returns (bool)
    {
        return self.usedNonces[sender][actionType][nonce];
    }

    /// @dev Updates the open positions by subaccount and quote token.
    function updateOpenPositions(Data storage self, bytes32 subaccount, address quoteToken, int128 delta) internal {
        self.openPositions[subaccount] = (self.openPositions[subaccount].toInt128() + delta).toUint256().toUint128();
        self.openPositionsByQuoteToken[subaccount][quoteToken] =
            (self.openPositionsByQuoteToken[subaccount][quoteToken].toInt128() + delta).toUint256().toUint128();
    }
}
"
    },
